<?php require 'includes/functions.php';require_login();$q=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$q->execute([user()['id']]);$orders=$q->fetchAll();$pageTitle='My Orders';require 'includes/header.php';require 'includes/navbar.php'; ?><main class="container my-5"><h1 class="section-title">My orders</h1><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_number'])?></td><td><?=date('d M Y',strtotime($o['created_at']))?></td><td><?=money($o['total_amount'])?></td><td><?=e(strtoupper($o['payment_method']))?> / <?=e($o['payment_status'])?></td><td><span class="badge text-bg-dark"><?=e(str_replace('_',' ',$o['order_status']))?></span></td><td><a class="btn btn-sm btn-outline-dark" href="<?=base('order-details.php?id='.$o['id'])?>">View</a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders): ?><div class="alert alert-secondary mt-3">No orders yet.</div><?php endif ?></main><?php require 'includes/footer.php'; ?>
